const webhook = $("Webhook").first().json.body || {};
const convData = $("Obtener Conversaciones").first().json;

const conversaciones = Array.isArray(convData.payload) ? convData.payload : [];
const ultimaConv = conversaciones.length > 0
  ? conversaciones.slice().sort(function(a, b) { return (b.id || 0) - (a.id || 0); })[0]
  : null;
const conversationId = ultimaConv ? ultimaConv.id : null;

const eventType      = String(webhook.event_type || '');
const codigo         = String(webhook.pedido_codigo || '?');
const tipoDespacho   = String(webhook.tipo_despacho || 'retiro');
const tiempoEstimado = webhook.tiempo_estimado ? String(webhook.tiempo_estimado) : null;

// ── helpers ────────────────────────────────────────────────────────────────
function money(v) {
  return '€' + Number(v || 0).toFixed(2).replace('.', ',');
}

// ── Mensaje confirmado enriquecido (comanda) ───────────────────────────────
function buildConfirmado() {
  const nombre     = webhook.nombre_cliente || null;
  const metodo     = String(webhook.metodo_pago || 'efectivo').toLowerCase();
  const subtotal   = Number(webhook.subtotal   || 0);
  const total      = Number(webhook.total      || 0);
  const costoEnvio = Number(webhook.costo_envio || 0);
  const direccion  = webhook.direccion || null;

  // Items
  let items = [];
  try {
    items = Array.isArray(webhook.items)
      ? webhook.items
      : JSON.parse(webhook.items || '[]');
  } catch { items = []; }

  // Despacho line
  let despachoLinea = '';
  if (tipoDespacho === 'delivery') {
    despachoLinea = '🛵 *Delivery*' + (direccion ? ' — ' + direccion : '');
    if (tiempoEstimado) despachoLinea += '\n⏱ Tiempo estimado: ' + tiempoEstimado;
  } else {
    despachoLinea = '🏪 *Retiro en local*';
    if (tiempoEstimado) despachoLinea += '\n⏱ Tiempo estimado: ' + tiempoEstimado;
  }

  // Items lines
  const itemsLineas = items.map(function(i) {
    const cantidad = Number(i.cantidad || i.quantity || 1);
    const nombre_item = String(i.nombre || i.name || '');
    const precio = Number(i.subtotal || (i.precio_unitario || i.unit_price || 0) * cantidad);
    let linea = cantidad + 'x ' + nombre_item + '  ' + money(precio);
    // Extras
    const extras = Array.isArray(i.extras) ? i.extras : [];
    if (extras.length > 0) {
      linea += '\n   + ' + extras.map(function(e) {
        return String(e.nombre || e.name || e.extra_nombre || '');
      }).filter(Boolean).join(', ');
    }
    return linea;
  }).join('\n');

  // Totales
  let totalesLineas = '';
  if (tipoDespacho === 'delivery' && costoEnvio > 0) {
    totalesLineas = 'Subtotal: ' + money(subtotal) + '\nEnvío: ' + money(costoEnvio) + '\n*TOTAL: ' + money(total) + '*';
  } else {
    totalesLineas = '*TOTAL: ' + money(total || subtotal) + '*';
  }

  // Método pago
  const metodosEmoji = { efectivo: '💵 Efectivo', tarjeta: '💳 Tarjeta', transferencia: '🏦 Transferencia', bizum: '📲 Bizum' };
  const metodoPagoLinea = metodosEmoji[metodo] || metodo;

  const partes = [
    '✅ *Pedido #' + codigo + ' CONFIRMADO*',
    nombre ? '👤 ' + nombre : null,
    despachoLinea,
    '',
    itemsLineas || '(sin detalle)',
    '',
    totalesLineas,
    metodoPagoLinea
  ].filter(function(x) { return x !== null; });

  return partes.join('\n');
}

// ── Mensajes estándar ──────────────────────────────────────────────────────
let despachoTexto = '';
if (tipoDespacho === 'delivery') {
  despachoTexto = tiempoEstimado
    ? 'Lo recibirás en aproximadamente ' + tiempoEstimado + '.'
    : 'Pronto lo recibirás en tu dirección.';
} else {
  despachoTexto = 'Hemos recibido tu pedido. Te avisaremos cuando esté listo para retirar.';
}

const mensajes = {
  confirmado:      buildConfirmado(),
  listo:           '🔔 ¡Tu pedido #' + codigo + ' está listo para retirar! Te esperamos en el local.',
  en_camino:       '🛵 Tu pedido #' + codigo + ' ya está en camino. ¡Pronto llega!',
  entregado:       '📦 Tu pedido #' + codigo + ' fue entregado. ¡Gracias por elegirnos!',
  cancelado:       '❌ Tu pedido #' + codigo + ' ha sido cancelado. Escríbenos si tienes alguna duda.',
  pago_confirmado: '✅ Confirmamos el pago de tu pedido #' + codigo + '. ¡Gracias!'
};

const mensaje = mensajes[eventType] || null;

return [{ json: { conversation_id: conversationId !== null ? String(conversationId) : null, mensaje: mensaje, event_type: eventType } }];
